  if (s[0] === 'operations') { if (s.length > 1) return success; return { items: [{ id: 'job-demo', owner: 'alex', kind: 'demo', label: 'Sample background job', status: 'ok', trigger: 'demo', started_at: ago(1), finished_at: ago(1), duration_ms: 20, attempts: 1, correlation_id: 'demo-correlation', retry_of: null, error: null, retryable: false, stale: false, detail: { demo: true } }], kinds: [{ kind: 'demo', label: 'Sample background job', ok: 1, failed: 0, running: 0 }], days: Number(p.get('days') || 7), scope: 'tenant' }; }
